#ifndef ARM_MATH_C_API_H
#define ARM_MATH_C_API_H

#ifdef __cplusplus
extern "C" {
#endif

// Robotics orientation conversions
void robotics_rpy2r(const float rpy[3], float R_out[9]);
void robotics_r2rpy(const float R[9], float rpy_out[3]);
void robotics_quat2r(const float q[4], float R_out[9]);
void robotics_r2quat(const float R[9], float q_out[4]);

// Homogeneous transform helpers
void robotics_rp2t(const float R[9], const float p[3], float T_out[16]);
void robotics_t2rp(const float T[16], float R_out[9], float p_out[3]);

// Math utils
float math_limit(float val, float min, float max);
float math_sign(float val);

#ifdef __cplusplus
}
#endif

#endif // ARM_MATH_C_API_H

